def parser_text(text):
    table=PARSER_TRANSLATIONS.get(CURRENT_LANG,{})
    if text in table:return table[text]
    if table:
        match=re.match(r'(\d+) asset\(s\) parsed successfully',text)
        if match:return table['Test Parsing']+' ✓ ('+match.group(1)+')'
        for prefix,key in (('Parsing failed:','Test Parsing'),('Unable to save:','Save Template'),('Unable to activate:','Set As Default'),('Unable to delete:','Delete Template'),('Saved templates could not be read. Default is active.','Parsing Templates')):
            if text.startswith(prefix):return table[key]+' — '+text[len(prefix):].strip()
    if text.startswith('Active Template:'):
        return text.replace('Active Template:',table.get('Active Template:','Active Template:'),1).replace('(Default)',table.get('(Default)','(Default)'))
    return text

