def load_ui_font():
    global _UI_FONT_LOADED
    if _UI_FONT_LOADED: return
    import base64,zlib
    from PyQt5.QtCore import QByteArray
    from PyQt5.QtGui import QFontDatabase
    for encoded in EMBEDDED_UI_FONTS:
        font_id=QFontDatabase.addApplicationFontFromData(QByteArray(zlib.decompress(base64.b64decode(encoded))))
        if font_id < 0: raise RuntimeError('Unable to load bundled Inter font')
    _UI_FONT_LOADED = True

