EMBEDDED_UI_FONTS = ('', '', '')

UI_ACCENTS = {
    'indigo': ('Soft Indigo', '#5F63D9'), 'blue': ('Ocean Blue', '#3672B4'),
    'teal': ('Soft Teal', '#237E78'), 'sage': ('Sage Green', '#557A56'),
    'lavender': ('Lavender', '#8164B3'), 'rose': ('Dusty Rose', '#AC5C7F'),
    'peach': ('Warm Peach', '#A9603B'), 'slate': ('Blue Slate', '#5D718A')}
UI_MODE, UI_ACCENT = 'light', 'indigo'
_UI_STYLES = weakref.WeakKeyDictionary()
_UI_ICONS = weakref.WeakKeyDictionary()
_UI_TEXTS = weakref.WeakKeyDictionary()
_UI_ICON_SPECS, _UI_ICON_CACHE, _UI_STYLE_CACHE = {}, {}, {}
UI_PREFS_FILE = os.path.join(WORKSPACE_DIR, 'ui_preferences.json')

def read_ui_preferences():
    try:
        with open(UI_PREFS_FILE,encoding='utf-8') as stream:prefs=json.load(stream)
        return prefs if isinstance(prefs,dict) else {}
    except (OSError,ValueError):return {}

def save_ui_preferences(updates):
    prefs=read_ui_preferences();prefs.update(updates)
    temporary=UI_PREFS_FILE+'.tmp'
    with open(temporary,'w',encoding='utf-8') as stream:json.dump(prefs,stream,ensure_ascii=False)
    os.replace(temporary,UI_PREFS_FILE)


def ui_mix(a, b, weight):
    a, b = QColor(a), QColor(b)
    return QColor(*[round(x*(1-weight)+y*weight) for x,y in zip((a.red(),a.green(),a.blue()),(b.red(),b.green(),b.blue()))]).name()

def ui_palette():
    primary = UI_ACCENTS[UI_ACCENT][1]
    dark = UI_MODE == 'dark'
    p = dict(bg='#101319' if dark else '#F4F6FA', panel='#191E28' if dark else '#FFFFFF',
             input='#141922' if dark else '#F8FAFD', text='#E9EDF5' if dark else '#182234',
             muted='#AAB4C7' if dark else '#62718A', faint='#7E8BA2' if dark else '#8A97AD',
             border='#343E50' if dark else '#D7DFEC', red='#F27D8B' if dark else '#C7334C',
             red_bg='#38232C' if dark else '#FFF0F3', attention='#EDAC5B' if dark else '#AE661E',
             attention_bg='#342C23' if dark else '#FFF3E5', primary=primary)
    p['accent'] = ui_mix(primary,'#FFFFFF',.40) if dark else primary
    p['tint'] = ui_mix(p['panel'],primary,.15 if dark else .07)
    p['hover'] = ui_mix(p['panel'],primary,.24 if dark else .12)
    return p

def ui_color(value, background=False):
    p = ui_palette(); value = value.upper()
    if value in {'#EF4444','#DC2626','#F87171','#B91C1C'}:
        return p['red_bg'] if background else p['red']
    if value in {'#F59E0B','#FFDD00'}:
        return p['attention_bg'] if background else p['attention']
    if value in {'#DBEAFE','#D1FAE5','#F0FDF4','#F3E8FF','#DCFCE7'}: return p['tint'] if background else p['accent']
    if value in {'#3B82F6','#10B981','#8B5CF6','#059669','#1E40AF','#065F46'}: return p['primary'] if background else p['accent']
    if value in {'#FFFFFF','#F3F4F6','#F8FAFC'}: return p['panel'] if value=='#FFFFFF' else p['input']
    if value in {'#D1D5DB','#E5E7EB'}: return p['border']
    if value in {'#111827','#1F2937','#374151','#000000'}: return p['text']
    if value in {'#475569','#6B7280','#9CA3AF'}: return p['input'] if background else p['muted']
    return value

def ui_font_weights(style):
    # Qt5 divides numeric stylesheet weights by 8. Use its QFont weights
    # (Medium=57, DemiBold=63) to select actual Inter 500/600 faces.
    return re.sub(r'(font-weight:\s*)(500|600)\b',
                  lambda match: match[1]+{'500':'456','600':'504'}[match[2]], style)

def ui_style(style):
    key = (UI_MODE, UI_ACCENT, style)
    if key in _UI_STYLE_CACHE: return _UI_STYLE_CACHE[key]
    p = ui_palette()
    result = re.sub(r'([\w-]+)\s*:([^;{}]+);', lambda m: m[1]+':'+re.sub(r'#[\da-fA-F]{6}',lambda c:ui_color(c[0], 'background' in m[1]),m[2])+';', style)
    # White foregrounds belong only on filled primary buttons.
    if not re.search(r'(?<![\w-])background-color\s*:\s*'+re.escape(p['primary']),result):
        result = re.sub(r'(?<![\w-])color\s*:\s*white\b', 'color: '+p['text'],result)
    result = re.sub(r'font-weight:\s*bold\b', 'font-weight: 600', result)
    result = re.sub(r'font-family:\s*[^;{}]+;', "font-family: '"+UI_FONT_FAMILY+"';", result)
    result = ui_font_weights(result)
    if len(_UI_STYLE_CACHE)>1024: _UI_STYLE_CACHE.clear()
    _UI_STYLE_CACHE[key]=result
    return result

def ui_markup(text):
    return re.sub(r'((?:background-color|color)\s*:\s*)(#[\da-fA-F]{6})',lambda m:m[1]+ui_color(m[2],'background' in m[1]),text)

def ui_icon(*args, **kwargs):
    original = dict(kwargs)
    if kwargs.get('color') != 'white' and 'color' in kwargs:
        kwargs['color']=ui_color(kwargs['color'])
    key=(UI_MODE,UI_ACCENT,args,tuple(sorted(kwargs.items())))
    if key not in _UI_ICON_CACHE:
        if len(_UI_ICON_CACHE)>256: _UI_ICON_CACHE.clear()
        _UI_ICON_CACHE[key]=qta.icon(*args,**kwargs)
    icon=QIcon(_UI_ICON_CACHE[key])
    _UI_ICON_SPECS[icon.cacheKey()]=(args,original)
    return icon

def refresh_ui_icon(widget,spec):
    args,kwargs=spec; kwargs=dict(kwargs); p=ui_palette()
    if kwargs.get('color')=='white' and p['primary'] not in widget.styleSheet():
        kwargs['color']=p['red'] if p['red_bg'] in widget.styleSheet() else (p['attention'] if p['attention_bg'] in widget.styleSheet() else p['muted'])
