class UiMixin:
    def setStyleSheet(self, style):
        if isinstance(self, QPushButton):
            if self.height()>30: style=style.replace('border-radius: 4px','border-radius: 8px').replace('border-radius: 6px','border-radius: 8px')
            if not self.text() and 'padding' not in style:
                style += ' QPushButton { padding: 0px; }' if '{' in style else ' padding: 0px;'
        _UI_STYLES[self]=style
        super().setStyleSheet(ui_style(style))
        if self in _UI_ICONS: refresh_ui_icon(self,_UI_ICONS[self])
    def setIcon(self, icon):
        spec=_UI_ICON_SPECS.get(icon.cacheKey())
        if spec:
            _UI_ICONS[self]=spec
            refresh_ui_icon(self,spec)
