class QPushButton(UiMixin,QPushButton):
    def __init__(self,*args,**kwargs):
        super().__init__(*args,**kwargs)
        self._hover=0.0
        self._animation=QPropertyAnimation(self,b'hoverAmount',self)
        self._animation.setDuration(150)
        self._animation.setEasingCurve(QEasingCurve.OutCubic)
        self.setCursor(Qt.PointingHandCursor)
    def get_hover(self): return self._hover
    def set_hover(self,value): self._hover=float(value);self.update()
    hoverAmount=pyqtProperty(float,get_hover,set_hover)
    def animate_hover(self,value):
        self._animation.stop();self._animation.setStartValue(self._hover)
        self._animation.setEndValue(value);self._animation.start()
    def enterEvent(self,event):
        if self.isEnabled(): self.animate_hover(1.0)
        super().enterEvent(event)
    def leaveEvent(self,event): self.animate_hover(0.0);super().leaveEvent(event)
    def paintEvent(self,event):
        super().paintEvent(event)
        if self._hover>.001 and self.isEnabled():
            painter=QPainter(self);painter.setRenderHint(QPainter.Antialiasing)
            color=QColor(ui_palette()['accent']);color.setAlpha(round(80*self._hover))
            painter.setPen(QPen(color,1.2));color.setAlpha(round(20*self._hover));painter.setBrush(color)
            painter.drawRoundedRect(self.rect().adjusted(1,1,-1,-1),min(8,self.height()/3),min(8,self.height()/3));painter.end()

class UiDelegate(QStyledItemDelegate):
    def sizeHint(self,option,index):
        size=super().sizeHint(option,index);size.setHeight(36);return size
    def paint(self,painter,option,index):
        p=ui_palette();painter.save();painter.setRenderHint(QPainter.Antialiasing)
        if option.state & (QStyle.State_Selected|QStyle.State_MouseOver):
            painter.setPen(Qt.NoPen);painter.setBrush(QColor(p['tint']));painter.drawRoundedRect(option.rect.adjusted(3,2,-3,-2),6,6)
        painter.setPen(QColor(p['text'] if option.state & QStyle.State_Enabled else p['faint']))
        painter.setFont(option.font);rect=option.rect.adjusted(12,0,-12,0)
        painter.drawText(rect,Qt.AlignVCenter|Qt.AlignLeft,option.fontMetrics.elidedText(str(index.data() or ''),Qt.ElideRight,rect.width()));painter.restore()

class QComboBox(UiMixin,QComboBox):
    def __init__(self,*args,**kwargs):
        super().__init__(*args,**kwargs)
        self.setView(QListView());self.view().setItemDelegate(UiDelegate(self.view()))
        self.setMinimumHeight(38);self.setMaxVisibleItems(8)
    def setStyleSheet(self,style):
        super().setStyleSheet(style+' QComboBox::drop-down { width: 26px; border: none; } QComboBox::down-arrow { image: none; }')
    def sync_popup(self):
        p=ui_palette();palette=QPalette(QApplication.palette())
        for role,key in ((QPalette.Base,'panel'),(QPalette.Window,'panel'),(QPalette.Text,'text'),(QPalette.Highlight,'tint'),(QPalette.HighlightedText,'text')): palette.setColor(role,QColor(p[key]))
        for widget in (self.view(),self.view().viewport(),self.view().window()):widget.setPalette(palette);widget.setAutoFillBackground(True)
        self.view().setStyleSheet(f"QListView {{ background-color: {p['panel']}; color: {p['text']}; border: 1px solid {p['border']}; padding: 5px; outline: 0; }}")
        self.view().viewport().setStyleSheet(f"background-color: {p['panel']};")
    def showPopup(self):
        self.sync_popup();super().showPopup()
        popup=self.view().window();origin=self.mapToGlobal(QPoint(0,self.height()+4))
        screen=QApplication.screenAt(origin) or QApplication.primaryScreen();bounds=screen.availableGeometry()
        popup.resize(max(self.width(),180),min(self.count(),8)*36+14)
        popup.move(max(bounds.left(),min(origin.x(),bounds.right()-popup.width())),min(origin.y(),bounds.bottom()-popup.height()))
    def paintEvent(self,event):
        super().paintEvent(event);painter=QPainter(self);painter.setRenderHint(QPainter.Antialiasing)
        painter.setPen(QPen(QColor(ui_palette()['muted']),1.7,Qt.SolidLine,Qt.RoundCap,Qt.RoundJoin))
        path=QPainterPath();x,y=self.width()-15,self.height()/2;path.moveTo(x-4,y-2);path.lineTo(x,y+2);path.lineTo(x+4,y-2);painter.drawPath(path);painter.end()

