class SortOptionsPanel(QFrame):
    def __init__(self,header):
        super().__init__(header.window())
        self.header=header;self.setObjectName('sortOptionsPanel')
        self.setStyleSheet('QFrame#sortOptionsPanel { background-color: #FFFFFF; border: 1px solid #D1D5DB; border-radius: 10px; }')
        self.option_buttons=[];layout=QVBoxLayout(self);layout.setContentsMargins(8,8,8,8);layout.setSpacing(3)
        for index in range(header.sort_combo.count()):
            button=QPushButton(header.sort_combo.itemText(index));button.setCheckable(True)
            button.setFixedHeight(31);button.setStyleSheet('QPushButton { text-align: left; padding: 5px 10px; border: none; border-radius: 6px; font-size: 12px; }')
            button.clicked.connect(lambda checked=False,i=index:self.choose(i))
            layout.addWidget(button);self.option_buttons.append(button)
        self.setFixedWidth(245);self.hide()
    def choose(self,index):
        self.header.sort_combo.setCurrentIndex(index);self.hide()
    def reposition(self):
        window=self.parentWidget();self.adjustSize()
        point=window.mapFromGlobal(self.header.sort_btn.mapToGlobal(QPoint(0,self.header.sort_btn.height()+5)))
        self.move(max(8,min(point.x(),window.width()-self.width()-8)),max(8,min(point.y(),window.height()-self.height()-8)))

class AssetListHeader(QWidget):
    def __init__(self, muted=False,sort_key=None,show_attached=True):
        super().__init__();self.show_attached=show_attached
        self.setMinimumWidth(0)
        self.setSizePolicy(QSizePolicy.Ignored,QSizePolicy.Preferred)
        self._layout=QVBoxLayout(self)
        self._layout.setContentsMargins(6,0,6,2)
        self._layout.setSpacing(6)
        self._top_layout=QHBoxLayout()
        self._top_layout.setSpacing(8)
        self._layout.addLayout(self._top_layout)
        self.icon_label=SectionIcon(muted)
        self.title_label=AssetTitle('')
        self.title_label.setStyleSheet('font-size: 13px; font-weight: 600; color: '+('#6B7280' if muted else '#1F2937')+'; background-color: transparent;')
        self.count_label=QLabel()
        self.count_label.setStyleSheet('font-size: 13px; font-weight: 600; color: #1F2937; background-color: transparent;')
        self.count_label.setMinimumWidth(0)
        self.sort_key=sort_key or ('uploaded' if muted else 'pending')
        self.sort_panel=None
        self.sort_combo=QComboBox(self)
        options=[('Default','default'),('Number: Low to High','number_asc'),('Number: High to Low','number_desc'),
                 ('Title: A–Z','title_asc'),('Title: Z–A','title_desc'),('Attached First','attached'),('Unattached First','unattached')]
        if muted:options += [('Upload Date: Newest','date_desc'),('Upload Date: Oldest','date_asc')]
        for name,key in options:self.sort_combo.addItem(name,key)
        self.sort_combo.hide()  # Selection model; visible control is the in-app menu.
        self.sort_controls=QWidget()
        controls=QHBoxLayout(self.sort_controls);controls.setContentsMargins(0,0,0,0);controls.setSpacing(4)
        self.sort_label=QLabel('Sort by:')
        self.sort_label.setStyleSheet('font-size: 12px; font-weight: 500; background-color: transparent;')
        self.sort_btn=QPushButton();self.sort_btn.setFixedSize(30,30)
        self.sort_btn.setIcon(ui_icon('fa5s.ellipsis-v',color='#6B7280'))
        self.sort_btn.setAccessibleName('Open '+self.sort_key+' sort options')
        self.lock_btn=QPushButton();self.lock_btn.setFixedSize(30,30);self.lock_btn.setCheckable(True)
        self.lock_btn.setAccessibleName('Remember '+self.sort_key+' sorting after restart')
        saved=read_ui_preferences().get('sorts',{})
        entry=saved.get(self.sort_key,{}) if isinstance(saved,dict) else {}
        if isinstance(entry,dict) and entry.get('locked') is True:
            index=self.sort_combo.findData(entry.get('order'))
            if index>=0:self.sort_combo.setCurrentIndex(index);self.lock_btn.setChecked(True)
        for widget in (self.sort_label,self.sort_btn,self.lock_btn):controls.addWidget(widget)
        self._top_layout.addWidget(self.icon_label)
        self._top_layout.addWidget(self.title_label,1)
        self._top_layout.addWidget(self.count_label)
        self._top_layout.addWidget(self.sort_controls)
        self.sort_btn.clicked.connect(self.toggle_sort_panel)
        self.lock_btn.toggled.connect(self.persist_sort)
        self.sort_combo.currentIndexChanged.connect(self.sort_changed)
        self.refresh_sort_controls()
        self._counter_stacked=False

    def refresh_sort_controls(self):
        locked=self.lock_btn.isChecked()
        self.sort_btn.setToolTip('Sort by: '+self.sort_combo.currentText())
        self.lock_btn.setIcon(ui_icon('fa5s.lock' if locked else 'fa5s.lock-open',color='white' if locked else '#6B7280'))
        self.lock_btn.setStyleSheet('background-color: #3B82F6; border: none; padding: 0px; border-radius: 7px;' if locked else 'padding: 0px; border-radius: 7px;')
        self.lock_btn.setToolTip(('Locked — sorting is saved after restart: ' if locked else 'Click to remember sorting after restart: ')+self.sort_combo.currentText())
        if self.sort_panel is not None:
            for index,button in enumerate(self.sort_panel.option_buttons):button.setChecked(index==self.sort_combo.currentIndex())

    def persist_sort(self,*args):
        sorts=read_ui_preferences().get('sorts',{})
        if not isinstance(sorts,dict):sorts={}
        if self.lock_btn.isChecked():sorts[self.sort_key]={'locked':True,'order':self.sort_combo.currentData()}
        else:sorts.pop(self.sort_key,None)
        try:save_ui_preferences({'sorts':sorts})
        except OSError as error:QMessageBox.warning(self,'Unable to Save Sort Preference',str(error))
        self.refresh_sort_controls()

    def sort_changed(self,*args):
        if self.lock_btn.isChecked():self.persist_sort()
        else:self.refresh_sort_controls()

    def toggle_sort_panel(self):
        if self.sort_panel is None:self.sort_panel=SortOptionsPanel(self)
        if self.sort_panel.isVisible():self.sort_panel.hide();return
        window=self.window()
        if hasattr(window,'appearance_panel'):window.appearance_panel.hide()
        for name in ('pending_header','uploaded_header'):
            header=getattr(window,name,None)
            if header is not None and header is not self and header.sort_panel is not None:header.sort_panel.hide()
        self.refresh_sort_controls();self.sort_panel.reposition();self.sort_panel.show();self.sort_panel.raise_()

    def update_counts(self,title,total,attached):
        self.total_assets,self.attached_assets=total,attached
        self.title_label.setText(title)
        self.count_label.setText(f'Total Assets: {total}'+(f'    Attached Assets: {attached}' if self.show_attached else ''))
        self.count_label.setAccessibleName(self.count_label.text())
        self.reflow()

    def reflow(self):
        needed=self.title_label.fontMetrics().horizontalAdvance(self.title_label.full_text)+self.count_label.fontMetrics().horizontalAdvance(self.count_label.text())+self.sort_controls.sizeHint().width()+70+getattr(self,'_extra_controls_width',0)
        stacked=self.width()<needed
        if stacked!=self._counter_stacked:
            if stacked:
                self._top_layout.removeWidget(self.count_label)
                self._layout.addWidget(self.count_label)
            else:
                self._layout.removeWidget(self.count_label)
                self._top_layout.insertWidget(self._top_layout.indexOf(self.sort_controls),self.count_label)
            self._counter_stacked=stacked
        self.count_label.setWordWrap(stacked)
        self.count_label.setAlignment(Qt.AlignLeft if stacked else Qt.AlignRight | Qt.AlignVCenter)
        self._top_layout.invalidate()
        self._layout.invalidate()
        self._layout.activate()

    def resizeEvent(self,event):
        super().resizeEvent(event)
        self.reflow()

def ui_application_style():
    p=ui_palette()
    return f"""
    QWidget {{ color: {p['text']}; font-family: '{UI_FONT_FAMILY}'; font-size: 13px; font-weight: 500; }}
    QMainWindow, QDialog {{ background-color: {p['bg']}; }}
    QLabel {{ background-color: transparent; }}
    QGroupBox {{ background-color: {p['panel']}; border: 1px solid {p['border']}; border-radius: 12px; margin-top: 18px; font-weight: 600; }}
    QGroupBox::title {{ subcontrol-origin: margin; left: 14px; padding: 0 6px; }}
    QListWidget {{ background-color: {p['panel']}; border: none; outline: 0; }}
    QListWidget#mainList::item {{ border: none; background-color: transparent; }}
    QListWidget#mainList::item:selected {{ background-color: {p['tint']}; color: {p['text']}; }}
    QPushButton {{ border: 1px solid {p['border']}; border-radius: 8px; padding: 6px 10px; background-color: {p['panel']}; }}
    QPushButton:hover {{ background-color: {p['hover']}; border-color: {p['accent']}; }}
    QPushButton:focus {{ border: 1px solid {p['accent']}; }}
    QPushButton:disabled {{ color: {p['faint']}; }}
    QPushButton:checked {{ background-color: {p['tint']}; border: 1px solid {p['accent']}; }}
    QComboBox {{ background-color: {p['panel']}; color: {p['text']}; border: 1px solid {p['border']}; border-radius: 8px; padding: 7px 28px 7px 10px; }}
    QToolTip {{ background-color: {p['panel']}; color: {p['text']}; border: 1px solid {p['border']}; padding: 6px; }}
    QScrollBar:vertical {{ width: 10px; background: {p['input']}; border: none; margin: 0; }}
    QScrollBar:horizontal {{ height: 10px; background: {p['input']}; border: none; margin: 0; }}
    QScrollBar::handle:vertical, QScrollBar::handle:horizontal {{ background: {p['border']}; border-radius: 5px; min-height: 24px; min-width: 24px; }}
    QScrollBar::handle:hover {{ background: {p['faint']}; }}
    QScrollBar::add-line:vertical, QScrollBar::sub-line:vertical {{ height: 0; }}
    QScrollBar::add-line:horizontal, QScrollBar::sub-line:horizontal {{ width: 0; }}
    QScrollBar::add-page, QScrollBar::sub-page {{ background: transparent; }}
    """

def ui_theme_jobs():
    p=ui_palette();app=QApplication.instance();palette=QPalette()
    event_filter=getattr(app,'_stock_ui_filter',None)
    if event_filter is not None and event_filter.tooltip is not None:event_filter.tooltip.hide()
    for role,key in ((QPalette.Window,'bg'),(QPalette.Base,'panel'),(QPalette.AlternateBase,'input'),(QPalette.Text,'text'),(QPalette.WindowText,'text'),(QPalette.Button,'panel'),(QPalette.ButtonText,'text'),(QPalette.Highlight,'tint'),(QPalette.HighlightedText,'text'),(QPalette.ToolTipBase,'panel'),(QPalette.ToolTipText,'text')):palette.setColor(role,QColor(p[key]))
    palette.setColor(QPalette.Disabled,QPalette.Text,QColor(p['faint']))
    app.setPalette(palette);app.setStyleSheet(ui_font_weights(ui_application_style()))
    jobs=[]
    for widget,style in list(_UI_STYLES.items()):
        if not sip.isdeleted(widget):jobs.append(lambda w=widget,s=style:super(UiMixin,w).setStyleSheet(ui_style(s)))
    for widget,spec in list(_UI_ICONS.items()):
        if not sip.isdeleted(widget):jobs.append(lambda w=widget,s=spec:refresh_ui_icon(w,s))
    for widget,text in list(_UI_TEXTS.items()):
        if not sip.isdeleted(widget):jobs.append(lambda w=widget,s=text:super(QLabel,w).setText(ui_markup(s)))
    for widget in app.allWidgets():
        if isinstance(widget,QComboBox):jobs.append(widget.sync_popup)
        if hasattr(widget,'refresh_visual_theme'):jobs.append(widget.refresh_visual_theme)
    return jobs

def apply_ui_theme(mode=None,accent=None):
    global UI_MODE,UI_ACCENT
    event_filter=getattr(QApplication.instance(),'_stock_ui_filter',None)
    if event_filter is not None and event_filter.tooltip is not None:event_filter.tooltip.hide()
    if mode in ('light','dark'): UI_MODE=mode
    if accent in UI_ACCENTS: UI_ACCENT=accent
    for job in ui_theme_jobs():job()

class UiSpinner(QWidget):
    def __init__(self,parent=None):
        super().__init__(parent);self.setFixedSize(56,56);self.angle=0;self.spinner_color=ui_palette()['accent']
        self.timer=QTimer(self);self.timer.timeout.connect(self.tick);self.timer.start(30)
    def tick(self):self.angle=(self.angle+12)%360;self.update()
    def paintEvent(self,event):
        painter=QPainter(self);painter.setRenderHint(QPainter.Antialiasing)
        painter.setPen(QPen(QColor(self.spinner_color),4,Qt.SolidLine,Qt.RoundCap));painter.drawArc(self.rect().adjusted(7,7,-7,-7),self.angle*16,260*16);painter.end()

def change_ui_appearance(window,mode,accent):
    global UI_MODE,UI_ACCENT
    if getattr(window,'_ui_busy',False): return
    window.appearance_panel.hide();window._ui_busy=True
    overlay=QFrame(window);overlay.setGeometry(window.rect());window._ui_overlay=overlay
    snapshot=QLabel(overlay);snapshot.setGeometry(overlay.rect());snapshot.setPixmap(window.grab())
    blur=QGraphicsBlurEffect(snapshot);blur.setBlurRadius(7);snapshot.setGraphicsEffect(blur)
    layout=QVBoxLayout(overlay);layout.addStretch()
    palette=ui_palette();card=QFrame(overlay);card.setObjectName('themeLoadingCard');card.setFixedSize(230,145)
    super(UiMixin,card).setStyleSheet(f"QFrame#themeLoadingCard {{ background-color: {palette['panel']}; border: 1px solid {palette['border']}; border-radius: 16px; }}")
    card_layout=QVBoxLayout(card);card_layout.setContentsMargins(20,18,20,18);card_layout.setSpacing(12)
    spinner=UiSpinner(card);card_layout.addWidget(spinner,0,Qt.AlignCenter)
    label=QLabel('Applying Theme',card);label.setObjectName('themeLoadingText')
    super(UiMixin,label).setStyleSheet(ui_font_weights(f"color: {palette['text']}; background-color: transparent; border: none; font-size: 16px; font-weight: 600;"))
    card_layout.addWidget(label,0,Qt.AlignCenter);layout.addWidget(card,0,Qt.AlignCenter);layout.addStretch()
    overlay.show();overlay.raise_()
    def begin():
        global UI_MODE,UI_ACCENT
        UI_MODE,UI_ACCENT=mode,accent
        jobs=deque(ui_theme_jobs())
        def step():
            deadline=time.monotonic()+.008
            while jobs and time.monotonic()<deadline:jobs.popleft()()
            if jobs:QTimer.singleShot(0,step)
            else:
                try:
                    save_ui_preferences({'mode':UI_MODE,'accent':UI_ACCENT})
                except OSError:pass
                spinner.timer.stop();overlay.hide();overlay.deleteLater();window._ui_overlay=None;window._ui_busy=False
                window.appearance_panel.refresh_selection()
        step()
    QTimer.singleShot(100,begin)

class AppearancePanel(QFrame):
    def __init__(self,window):
        super().__init__(window);self.window=window;self.setObjectName('appearancePanel');self.setFixedWidth(340)
        self.setStyleSheet('QFrame#appearancePanel { background-color: #FFFFFF; border: 1px solid #D1D5DB; border-radius: 12px; }')
