        pins=self.main_window.sorted_assets(pins,self.header.sort_combo.currentData());self.listing.clear()
        for asset in pins:
            image=self.main_window.get_asset_image(asset['id']);thumb=os.path.join(WORKSPACE_DIR,THUMBNAILS_FOLDER,f"{asset['id']:03d}.jpg")
            item=QListWidgetItem(self.listing);item.setData(Qt.UserRole,asset['id']);item.setSizeHint(QSize(0,46));self.listing.setItemWidget(item,ListItemWidget(asset,self.main_window,thumb if image and os.path.isfile(thumb) else image))
        self.export_batch_btn.setEnabled(bool(pins));self.update_footer()
